INSERT INTO document.document_page (
    id, org_id, document_id, page_no, page_hash, text_layer, text, usable, created_by,
    updated_by
)
VALUES
    ('a0000000-0000-0000-0000-0000d4003001', :org::uuid, 'a0000000-0000-0000-0000-0000d3003000', 1, '4e301f3da4d1cd3795baf8c15d9ec245e635e3f1066e24e15447fcffc5a159da', true,
     'Chính sách chiết khấu theo số lượng cho đại lý

Công ty Adventure Works Cycles. Quyết định số 14/2010/QĐ-AWC ngày 20/12/2010. Chính sách áp dụng từ ngày 29/12/2010 đến hết ngày 28/12/2013.

Đại lý mua cùng một sản phẩm trên một dòng đơn hàng được chiết khấu theo số lượng như sau:

Số lượng trên một dòng đơn | Chiết khấu
Từ 11 đến 14 sản phẩm | 2%
Từ 15 đến 24 sản phẩm | 5%
Từ 25 đến 40 sản phẩm | 10%
Từ 41 đến 60 sản phẩm | 15%
Trên 60 sản phẩm | 20%

Mỗi dòng đơn hàng chỉ được áp một chương trình khuyến mại; chiết khấu theo số lượng không cộng dồn với chương trình khác.

Khách hàng mua qua Internet không được chiết khấu theo số lượng. Một số dòng đơn Internet mang mã chiết khấu số lượng nhưng mức giảm bằng 0; các dòng đó không được tính là doanh thu khuyến mại.',
     true, :engineer::uuid, :engineer::uuid);

INSERT INTO document.chunk (
    id, org_id, document_id, collection_id, page_from, page_to, section_path,
    context_header, text, tokens, effective_from, pii_masked, injection_suspected
)
VALUES
    ('a0000000-0000-0000-0000-0000d5003001', :org::uuid, 'a0000000-0000-0000-0000-0000d3003000', 'a0000000-0000-0000-0000-0000d1001000', 1, 1,
     NULL, 'Chính sách chiết khấu theo số lượng cho đại lý | Số 14/2010/QĐ-AWC',
     'Chính sách chiết khấu theo số lượng cho đại lý

Công ty Adventure Works Cycles. Quyết định số 14/2010/QĐ-AWC ngày 20/12/2010. Chính sách áp dụng từ ngày 29/12/2010 đến hết ngày 28/12/2013.

Đại lý mua cùng một sản phẩm trên một dòng đơn hàng được chiết khấu theo số lượng như sau:

Số lượng trên một dòng đơn | Chiết khấu Từ 11 đến 14 sản phẩm | 2% Từ 15 đến 24 sản phẩm | 5% Từ 25 đến 40 sản phẩm | 10% Từ 41 đến 60 sản phẩm | 15% Trên 60 sản phẩm | 20%

Mỗi dòng đơn hàng chỉ được áp một chương trình khuyến mại; chiết khấu theo số lượng không cộng dồn với chương trình khác.

Khách hàng mua qua Internet không được chiết khấu theo số lượng. Một số dòng đơn Internet mang mã chiết khấu số lượng nhưng mức giảm bằng 0; các dòng đó không được tính là doanh thu khuyến mại.',
     162, date '2010-12-29', true, false);

