INSERT INTO document.document_page (
    id, org_id, document_id, page_no, page_hash, text_layer, text, usable, created_by,
    updated_by
)
VALUES
    ('a0000000-0000-0000-0000-0000d4008001', :org::uuid, 'a0000000-0000-0000-0000-0000d3008000', 1, 'e29a6b529b8595c1005825d3a2bd5e41e485259a50fc6c08bf84e39ea987262b', true,
     'Quy chế kế hoạch ngân sách và so sánh với thực hiện

Công ty Adventure Works Cycles. Quyết định số 15/2010/QĐ-AWC ngày 15/12/2010 của Tổng giám đốc ban hành quy chế lập kế hoạch ngân sách và so sánh số thực hiện với kế hoạch.

Điều 1. Hai kịch bản số liệu

Số liệu tài chính có hai kịch bản: Thực hiện (Actual) và Kế hoạch (Budget). Bảng tài chính (fact_finance) ghi cả hai kịch bản trên cùng một bảng, phân biệt bằng cột kịch bản (scenario).

Điều 2. Không cộng thực hiện với kế hoạch

1. Không bao giờ cộng số thực hiện với số kế hoạch.

2. So sánh thực hiện với kế hoạch là đặt hai số cạnh nhau hoặc tính chênh lệch, theo cùng tài khoản và cùng tháng.

Điều 3. Kịch bản dự báo

Kịch bản Dự báo (Forecast) có trong danh mục kịch bản nhưng công ty không lập dự báo. Câu hỏi về số dự báo được trả lời là không có số liệu.',
     true, :engineer::uuid, :engineer::uuid),
    ('a0000000-0000-0000-0000-0000d4008002', :org::uuid, 'a0000000-0000-0000-0000-0000d3008000', 2, '062e89d2a61b64958c1f46b2c8b358f6cf42f0682bb564ff9662b9ed3c3f37d2', true,
     'Điều 4. Đọc số tiền theo tài khoản

Số tiền (amount) của bảng tài chính chỉ có nghĩa theo từng tài khoản (account): doanh thu, chi phí và tài sản nằm chung một cột, nên không cộng toàn bộ cột số tiền.

Điều 5. Thời gian có kế hoạch

Kế hoạch được lập theo tháng, từ tháng 12/2010 đến tháng 11/2011. Sau tháng 11/2011 không có số kế hoạch: so sánh thực hiện với kế hoạch cho các tháng sau được trả lời là chưa có kế hoạch, không lấy số kế hoạch của năm trước.

Điều 6. Hiệu lực

Quy chế có hiệu lực từ ngày 01/01/2011.',
     true, :engineer::uuid, :engineer::uuid);

