INSERT INTO document.document_page (
    id, org_id, document_id, page_no, page_hash, text_layer, text, usable, created_by,
    updated_by
)
VALUES
    ('a0000000-0000-0000-0000-0000d4014001', :org::uuid, 'a0000000-0000-0000-0000-0000d3014000', 1, 'c4afc2d58ee15248ffb7c5d474ecfd6715086ff5ff30c388707c02c061edd280', true,
     'Dealer Return and Warranty Policy

Adventure Works Cycles. Policy No. 10/2013/POL-AWC, issued 20 June 2013, effective 1 July 2013.

This policy supersedes Policy No. 06/2011/POL-AWC (Dealer Return Policy) from 1 July 2013.

1. A dealer may return unsold, undamaged bicycles within 45 days of delivery for credit.

2. A restocking fee of 10% of the invoiced amount is charged on every return.

3. Components and accessories may be returned within 60 days in their original packaging.

4. Frames are covered by a three-year warranty against manufacturing defects; other parts by one year.

5. Products sold under a Discontinued Product clearance promotion are final sale and cannot be returned.

6. A warranty claim must give the sales order number of the original sale.',
     true, :engineer::uuid, :engineer::uuid);

